// ===== netlify/functions/_agent/normalize.mjs =====
function norm(value='') {
  return String(value)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/[^a-z0-9%²³.#/+-]+/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function tokens(value='') {
  const stop = new Set(['de','la','el','los','las','un','una','y','o','para','con','sin','del','al','en','por','se','que','mi','su','a']);
  return [...new Set(norm(value).split(' ').filter(t => t.length > 1 && !stop.has(t)))];
}

function num(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(String(value).replace(',','.'));
  return Number.isFinite(n) ? n : null;
}

function round2(n){ return Math.round((Number(n)||0)*100)/100; }
function money(n){ return round2(n); }


