function techniqueFor(concept={}){
  const text=`${concept.name||''} ${concept.description||''}`;
  return VERIFIED_TECHNIQUES.find(t=>(!t.codeRx||t.codeRx.test(concept.code||''))&&(!t.nameRx||t.nameRx.test(text.toLowerCase())))||VERIFIED_TECHNIQUES.at(-1);
}

