function appliedRules(text=''){
 const t=String(text).toLowerCase();
 const explicitlyNoAsbestos=/sin\s+amianto/.test(t);
 return EXPERIENCE_RULES.filter(r=>r.rx.test(t)&&!(r.id==='ASBESTOS_001'&&explicitlyNoAsbestos));
}


