function has(input,key){const d=input.dimensions||{},v=input[key]??d[key];return v!==undefined&&v!==null&&String(v).trim()!=='';}
function detectProjectMode(input={}){
 const forced=String(input.projectMode||'auto');if(['repair','renovation','new_build'].includes(forced))return forced;
 const t=norm([input.description,input.additionalInfo,input.projectStatus].filter(Boolean).join(' '));
 if(NEW_BUILD_RX.test(t))return'new_build';
 if(INTEGRAL_RX.test(t))return'renovation';
 const nb=['cimentacion','encofrado','forjado','pilares','cerramientos','obra desde cero'].filter(x=>t.includes(norm(x))).length;if(nb>=3)return'new_build';
 if(REPAIR_RX.test(t)&&t.length<220)return'repair';return'renovation';
}
function phaseStatus(p,t,integral){const explicit=(p.triggers||[]).some(x=>t.includes(norm(x)));const active=!!p.required||explicit||integral;return{...p,explicit,status:active?(p.required?'required':'included'):'optional'};}
function buildScope(input={}){
 const mode=detectProjectMode(input),t=norm([input.description,input.additionalInfo,input.structureSystem,input.roofType,input.partitionSystem].filter(Boolean).join(' '));
 if(mode==='new_build'){
  const phases=NEW_BUILD_PHASES.map(p=>phaseStatus(p,t,true));
  const missing=NEW_BUILD_REQUIRED_INPUTS.filter(x=>!has(input,x.key));
  const ps=norm(input.projectStatus||'');
  const negativeProject=/(sin|no dispone|no tengo|pendiente|en redaccion|en redaccion|solo basico|proyecto basico)/.test(ps);
  const hasExec=!negativeProject&&(/execution|ejecucion/.test(ps)||/proyecto de ejecucion/.test(t));
  let completeness='preliminary';if(hasExec&&missing.length<=2)completeness='detailed';if(hasExec&&missing.length===0&&num(input.dimensions?.builtArea))completeness='ready_for_pricing_review';
  return{mode,phases,requiredInputs:missing,completeness,integral:true};
 }
 const integral=INTEGRAL_RX.test(t);const phases=RENOVATION_PHASES.map(p=>phaseStatus(p,t,integral));
 const active=phases.filter(p=>p.status!=='optional');
 let completeness='draft';if(mode==='repair'&&active.length<=8)completeness='focused';if(integral)completeness='integral_scope';
 return{mode,phases,requiredInputs:[],completeness,integral};
}
function scopeQuestions(scope){const q=[];for(const p of scope.phases.filter(x=>x.status!=='optional'))q.push(...(p.questions||[]));for(const x of scope.requiredInputs||[])q.unshift(`Falta indicar: ${x.label}.`);return[...new Set(q)];}
function scopeSearches(scope){const q=[];for(const p of scope.phases.filter(x=>x.status!=='optional'))q.push(...(p.searches||[]));return[...new Set(q)];}


