function outputText(data){for(const o of data?.output||[])if(o.type==='message')for(const c of o.content||[])if(c.type==='output_text'&&c.text)return c.text;return data?.output_text||'';}
const schema={type:'object',additionalProperties:false,properties:{
 projectType:{type:'string'},summary:{type:'string'},estimateLevel:{type:'string',enum:['preliminary','detailed','ready_for_review']},
 technicalWorks:{type:'array',items:{type:'string'}},assumptions:{type:'array',items:{type:'string'}},missingQuestions:{type:'array',items:{type:'string'}},warnings:{type:'array',items:{type:'string'}},
 selectedLines:{type:'array',items:{type:'object',additionalProperties:false,properties:{code:{type:'string'},quantity:{anyOf:[{type:'number'},{type:'null'}]},reason:{type:'string'},confidence:{type:'number'}},required:['code','quantity','reason','confidence']}},
 phaseReview:{type:'array',items:{type:'object',additionalProperties:false,properties:{id:{type:'string'},status:{type:'string',enum:['included','conditional','not_applicable','needs_data']},note:{type:'string'}},required:['id','status','note']}}
},required:['projectType','summary','estimateLevel','technicalWorks','assumptions','missingQuestions','warnings','selectedLines','phaseReview']};

export async function interpretWithOpenAI({input,local}){
 const key=process.env.OPENAI_API_KEY;if(!key)return null;
 const model=process.env.OPENAI_QUOTE_MODEL||'gpt-5.6';
 const allowed=local.candidates.slice(0,140).map(x=>({code:x.code,unit:x.unit,name:x.name,price:x.price,chapter:x.chapter,description:String(x.description||'').slice(0,520),query:x.query}));
 const phases=local.scope.phases.filter(p=>p.status!=='optional').map(p=>({id:p.id,title:p.title,required:p.required,status:p.status,risks:p.risks}));
 const payload={description:input.description,additionalInfo:input.additionalInfo||'',location:input.location||'',mode:local.scope.mode,dimensions:input.dimensions||{},measurements:local.measurements,projectStatus:input.projectStatus||'',structureSystem:input.structureSystem||'',roofType:input.roofType||'',partitionSystem:input.partitionSystem||'',buildingType:input.buildingType||'',activePhases:phases,localRules:local.rules.map(r=>({id:r.id,title:r.title,checks:r.checks})),regulatoryGates:local.gates,candidates:allowed};
 const content=[{type:'input_text',text:`Analiza este encargo de construcción como jefe de estudios/presupuestación. Reglas obligatorias:\n- No inventes medidas, sistemas, materiales ni variantes.\n- Solo puedes seleccionar códigos de CANDIDATES y únicamente si la variante coincide con lo especificado. Si falta formato, espesor, sistema, medidas o proyecto, pregunta en vez de seleccionar una variante arbitraria.\n- Distingue trabajo solicitado, trabajo técnicamente derivado y trabajo condicionado.\n- Para reforma integral revisa toda la secuencia; para obra nueva no cierres estructura/cimentación sin proyecto y mediciones.\n- Detecta impermeabilización en cambio bañera->ducha, medios auxiliares por altura, ayudas a industriales, residuos, soportes, remates y duplicidades.\n- No conviertas una estimación preliminar en oferta cerrada.\n- Los precios del candidato son del Libro 48/2026; no los sustituyas.\n- Si una foto permite observar algo, descríbelo como observación visual, no como medición exacta salvo escala fiable.\n\nDATOS:\n${JSON.stringify(payload)}` }];
 for(const image of (input.images||[]).slice(0,3))if(typeof image==='string'&&image.startsWith('data:image/'))content.push({type:'input_image',image_url:image,detail:'auto'});
 const res=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify({model,input:[{role:'user',content}],text:{format:{type:'json_schema',name:'construction_quote_analysis',strict:true,schema}},reasoning:{effort:'medium'},store:false,max_output_tokens:7000})});
 const txt=await res.text();let data;try{data=JSON.parse(txt);}catch{throw new Error(`OpenAI devolvió respuesta no JSON (${res.status})`);}if(!res.ok)throw new Error(data?.error?.message||`OpenAI respondió ${res.status}`);
 const out=outputText(data);if(!out)throw new Error('OpenAI no devolvió análisis estructurado.');
 try{return JSON.parse(out);}catch{throw new Error('No se pudo interpretar la salida estructurada de OpenAI.');}
}


// ===== netlify/functions/_agent/pricing-engine.mjs =====
function markupFactor(policy=INTERNAL_PRICING){
  if(policy.markupMode==='compound') return (1+policy.industrialProfit)*(1+policy.generalExpenses)*(1+policy.marketUpdate);
  return 1+policy.industrialProfit+policy.generalExpenses+policy.marketUpdate;
}

function priceLine(line,policy=INTERNAL_PRICING){
  const quantity=line.quantity===null||line.quantity===undefined?null:Number(line.quantity);
  const base=Number(line.baseUnitPrice??line.price)||0;
  const marketFactor=Number(line.marketFactor)||1;
  const adjustedBase=money(base*marketFactor);
  const finalUnit=money(adjustedBase*markupFactor(policy));
  return {...line,baseUnitPrice:money(base),adjustedBaseUnitPrice:adjustedBase,finalUnitPrice:finalUnit,subtotal:quantity===null?null:money(finalUnit*quantity)};
}

function summarize(lines=[],vat=INTERNAL_PRICING.defaultVat){
  const priced=lines.filter(l=>l.quantity!==null&&l.subtotal!==null);
  const net=money(priced.reduce((s,l)=>s+(Number(l.subtotal)||0),0));
  const vatRate=INTERNAL_PRICING.allowedVat.includes(Number(vat))?Number(vat):INTERNAL_PRICING.defaultVat;
  const vatAmount=money(net*vatRate), total=money(net+vatAmount);
  return {net,vatRate,vatAmount,total,currency:INTERNAL_PRICING.currency,pricedLines:priced.length,pendingLines:lines.length-priced.length};
}


// ===== netlify/functions/_agent/question-filter.mjs =====
function filterAnsweredQuestions(questions=[],input={},measurements={}){
  const text=norm([input.description,input.additionalInfo,input.location,input.projectStatus,input.structureSystem,input.roofType].filter(Boolean).join(' '));
  const d=input.dimensions||{};
  return questions.filter(q=>{
    const n=norm(q);
    if(n.startsWith('falta indicar')){
      if(n.includes('superficie construida')&&d.builtArea) return false;
      if(n.includes('numero de plantas')&&d.floors) return false;
      if(n.includes('altura aproximada')&&d.storeyHeight) return false;
      if(n.includes('estado del proyecto')&&input.projectStatus) return false;
      if(n.includes('sistema estructural')&&input.structureSystem) return false;
      if(n.includes('tipo de cubierta')&&input.roofType) return false;
    }
    if(n.includes('medida tendra el plato')&&d.showerLength&&d.showerWidth) return false;
    if(n.includes('cuantas plantas')&&d.floors) return false;
    if(n.includes('metros lineales')&&d.scaffoldLength) return false;
    if(n.includes('altura aproximada')&&(d.scaffoldHeight||d.storeyHeight)) return false;
    if(n.includes('especialmente expuesta al viento')&&/viento|tramuntana|expuesta/.test(text)) return false;
    if(n.includes('pretende reutilizar')&&/reutil|recuper/.test(text)) return false;
    if(n.includes('en que planta')&&/(primer|segundo|tercer|cuarto|quinto|1|2|3|4|5)\s*(piso|planta)/.test(text)) return false;
    if(n.includes('vivienda o local debajo')&&/(vivienda|vecino|local).*debajo|debajo.*(vivienda|vecino|local)/.test(text)) return false;
    if(n.includes('cuantos sumideros')&&/\b\d+\s+sumider/.test(text)) return false;
    if(n.includes('superficie')&&(d.area||d.roofArea||d.builtArea||measurements.floorArea||measurements.roofArea||measurements.builtArea)) return false;
    if(n.includes('proyecto de ejecucion')&&(/ejec/.test(String(input.projectStatus||'').toLowerCase())||/execution/.test(String(input.projectStatus||'').toLowerCase()))) return false;
    if(n.includes('sistema de cimentacion')&&/zapata|losa|micropil|pilote/.test(text)) return false;
    if(n.includes('sistema estructural')&&input.structureSystem) return false;
    if(n.includes('cubierta es plana')&&input.roofType) return false;
    if(n.includes('cuantas puertas')&&d.doors) return false;
    if(n.includes('cuantos baños')&&d.bathrooms) return false;
    if(n.includes('amianto')&&n.includes('confirmado')&&/con amianto|contiene amianto|amianto confirmado/.test(text)) return false;
    if(n.includes('duracion prevista')&&n.includes('andamio')&&d.scaffoldRentalDays) return false;
    if(n.includes('altura real')&&n.includes('andamiar')&&d.scaffoldHeight&&d.scaffoldLength) return false;
    return true;
  });
}


// ===== netlify/functions/_agent/audit-engine.mjs =====
function worst(a,b){const r={green:0,yellow:1,red:2};return r[b]>r[a]?b:a;}
function enrichTechnical(line,{local,input}={}){
 const tech=techniqueFor(line),sources=(tech.sources||[]).map(k=>TECHNICAL_SOURCES[k]).filter(Boolean);
 let status=tech.id==='GENERIC_BOOK'?'yellow':'green';const notes=[];
 {const lt=norm(`${line.name} ${line.description}`);if(!/sin\s+amianto/.test(lt)&&/amianto|fibrocemento con amianto/.test(lt)){status='red';notes.push('Trabajo con amianto: referencia económica condicionada a empresa RERA, plan aprobado y procedimiento específico.');}}
 if(line.quantity==null){status=worst(status,'yellow');notes.push('Medición pendiente.');}
 if((local?.scope?.mode==='new_build')&&/ciment|estructura|pilar|viga|forjado|escalera.*hormig/.test(norm(`${line.name} ${line.description}`))){
  const ps=norm(input?.projectStatus||'');const hasExec=!/(sin|no dispone|no tengo|pendiente|solo basico|proyecto basico)/.test(ps)&&/ejecucion|execution/.test(ps);if(!hasExec){status='red';notes.push('No cerrar partida estructural sin proyecto de ejecución/mediciones verificadas.');}
 }
 return {...line,verification:status,verificationNotes:notes,executionSteps:tech.steps,preconditions:tech.preconditions,measurementCriterion:tech.measurement,inclusions:tech.includes||[],exclusions:tech.excludes||[],evidence:sources.map(s=>({label:s.label,kind:s.kind,verified:s.verified}))};
}

function audit({input,local,lines,ai}){
 const t=norm([input.description,input.additionalInfo].filter(Boolean).join(' ')),warnings=[],checks=[],blockers=[];
 if(local.scope.mode==='new_build'){
  {const ps=norm(input.projectStatus||'');const hasExec=!/(sin|no dispone|no tengo|pendiente|solo basico|proyecto basico)/.test(ps)&&/ejecucion|execution/.test(ps);if(!hasExec)blockers.push('Obra nueva sin proyecto de ejecución/mediciones suficientes: solo estimación preliminar.');}
  if(!input.dimensions?.builtArea)blockers.push('Falta superficie construida total.');
  checks.push('Secuencia de obra nueva revisada por 12 fases maestras.');
 }else if(local.scope.integral){checks.push('Reforma integral revisada por 30 familias de proceso.');}
 if(/banera por ducha|bañera por ducha|cambiar.*(?:banera|bañera)|poner.*plato.*ducha|colocar.*plato.*ducha|instalar.*plato.*ducha|ducha de obra|hacer.*ducha/.test(t)){
  const has=lines.some(l=>/impermeabil/.test(norm(`${l.name} ${l.description}`)));
  if(!has)warnings.push('Ducha/zona húmeda: la impermeabilización debe confirmarse y presupuestarse; no se da por incluida automáticamente.');
  checks.push('Nueva zona de ducha/cambio bañera-ducha: impermeabilización, desagüe, pendientes y encuentros revisados.');
 }
 if(/andamio|tejado|cubierta/.test(t)){
  if(/andamio/.test(t)&&!local.measurements.scaffoldArea)warnings.push('Andamio: faltan altura y/o longitud para calcular superficie real.');
  checks.push('Altura, geometría, montaje/desmontaje, transporte, anclajes/protecciones y alquiler deben revisarse por configuración real.');
 }
 if(lines.some(l=>l.code==='0XA110b')){const days=Number(input?.dimensions?.scaffoldRentalDays)||null;if(days&&days!==45)warnings.push(`La partida 0XA110b del Libro 48 referencia 45 días de alquiler; se han indicado ${days} días. No extrapolar automáticamente: ajustar con oferta/partida compatible.`);else if(!days)warnings.push('El alquiler 0XA110b del Libro 48 está definido para 45 días; confirmar que la duración prevista es compatible.');}
 if(lines.some(l=>l.code==='QTT210m')){
  const dup=lines.filter(l=>l.code!=='QTT210m'&&/cumbrera|caballet|remate lateral/.test(norm(`${l.name} ${l.description}`)));
  if(dup.length)warnings.push('Posible duplicidad: QTT210m ya contempla piezas de caballete, remate lateral y piezas especiales según Libro 48.');
 }
 if(lines.some(l=>/^HYA010|^PYA010/.test(l.code)))warnings.push('Ayudas de albañilería: comprobar la oferta del industrial para no duplicar rozas, huecos, recibidos o remates ya incluidos.');
 if(/amianto|fibrocemento/.test(t)&&!/sin\s+amianto/.test(t))blockers.push('Posible amianto: confirmar material y aplicar RD 396/2006; si contiene amianto, empresa especializada inscrita en RERA y plan de trabajo aprobado antes de ejecutar.');
 if(/amianto|fibrocemento/.test(t)&&!/sin\s+amianto/.test(t)){const aa=Number(input?.dimensions?.roofArea||input?.dimensions?.demolitionArea)||null;if(aa&&aa>100)warnings.push('El Libro 48 cargado dispone de variantes DQC030 hasta 100 m²; para una superficie mayor no se extrapola automáticamente el precio y debe seleccionarse/contrastar una variante u oferta compatible.');}
 if(/tirar.*pared|quitar.*pared|muro de carga|abrir.*hueco/.test(t))blockers.push('Posible afección estructural: no cerrar solución ni precio sin comprobar carácter portante y documentación técnica.');
 if(lines.some(l=>l.quantity==null))warnings.push('Hay partidas sin medición: el total económico mostrado es parcial.');
 if(!lines.length&&(local.questions||[]).length)warnings.push('Faltan datos técnicos para seleccionar partidas concretas del Libro 48; el resultado es preliminar y no debe tratarse como presupuesto cerrado.');
 for(const g of local.gates||[]){if(g.status==='red')blockers.push(g.message);else warnings.push(g.message);}
 const lineHasRed=lines.some(l=>l.verification==='red'),lineHasYellow=lines.some(l=>l.verification==='yellow');
 let score=100;score-=Math.min(45,blockers.length*15);score-=Math.min(30,warnings.length*4);score-=Math.min(20,lines.filter(l=>l.quantity==null).length*3);if(lineHasRed)score-=10;else if(lineHasYellow)score-=4;score=Math.max(0,score);
 const status=(blockers.length||lineHasRed)?'red':(warnings.length||lineHasYellow)?'yellow':'green';
 return{status,score,warnings:[...new Set(warnings)],blockers:[...new Set(blockers)],checks:[...new Set(checks)]};
}


// ===== netlify/functions/quote-agent.mjs =====
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
function sanitizeSelected(selected=[],allowed=new Set()){const seen=new Set(),out=[];for(const x of selected){if(!x?.code||seen.has(x.code)||!allowed.has(x.code))continue;seen.add(x.code);out.push(x);}return out;}
function enrichLines(selected,local,input){
 const source=selected.length?selected:local.lines,out=[];
 for(const x of source){const c=getConcept(x.code,input.language||'es');if(!c)continue;const lm=local.lines.find(z=>z.code===x.code);const quantity=x.quantity??lm?.quantity??null;
  const priced=priceLine({code:x.code,name:c.name,description:c.description,unit:c.unit,chapter:c.chapter,quantity,baseUnitPrice:c.price,components:getComponents(x.code),reason:x.reason||lm?.reason||'',confidence:x.confidence??lm?.confidence??0.5,source:'Libro 48/2026',intent:lm?.intent||''});
  out.push(enrichTechnical(priced,{local,input}));
 }
 return out;
}
function estimateLevel(local,ai,lines,a){
 if(ai?.estimateLevel)return ai.estimateLevel;if(a.blockers.length)return'preliminary';
 if(local.scope.mode==='new_build')return local.scope.completeness==='ready_for_pricing_review'&&lines.length&&lines.every(l=>l.quantity!=null)?'ready_for_review':local.scope.completeness==='detailed'?'detailed':'preliminary';
 if(lines.length&&lines.every(l=>l.quantity!=null)&&a.status!=='red')return'ready_for_review';return lines.some(l=>l.quantity!=null)?'detailed':'preliminary';
}
function publicLine(l){return{code:l.code,name:l.name,description:l.description,unit:l.unit,chapter:l.chapter,quantity:l.quantity,finalUnitPrice:l.finalUnitPrice,subtotal:l.subtotal,reason:l.reason,confidence:l.confidence,source:l.source,verification:l.verification,verificationNotes:l.verificationNotes,executionSteps:l.executionSteps,preconditions:l.preconditions,measurementCriterion:l.measurementCriterion,evidence:l.evidence};}

export default async(req)=>{
 if(req.method!=='POST')return json({error:'Método no permitido'},405);
 try{
  const input=await req.json();const action=input.action||'analyze';
  if(action==='health')return json({ok:true,version:'3.0.0',pricebook:pricebookMeta,openaiConfigured:!!process.env.OPENAI_API_KEY});
  if(action==='search')return json({meta:pricebookMeta,results:searchPricebook(input.query||'',{limit:40,language:input.language||'es'}).map(x=>({code:x.code,unit:x.unit,name:x.name,description:x.description,price:x.price,chapter:x.chapter,score:x.score}))});
  if(action==='chapters')return json({meta:pricebookMeta,renovation:RENOVATION_PHASES,newBuild:NEW_BUILD_PHASES,pricebookChapters:chapterNames()});
  if(!input?.description||String(input.description).trim().length<8)return json({error:'Describe la obra con algo más de detalle.'},400);
  const local=localInterpret(input);let ai=null,aiError=null;
  try{ai=await interpretWithOpenAI({input,local});}catch(e){aiError=e?.message||'Error IA';console.error('Optimus V3 AI fallback:',e);}
  const allowed=new Set([...local.candidates.map(x=>x.code),...local.lines.map(x=>x.code)]);
  const requestText=String([input.description,input.additionalInfo].filter(Boolean).join(' ')).toLowerCase();
  const noAsbestos=/sin\s+amianto/.test(requestText),asbestosUncertain=/no sabemos.*amianto|no se sabe.*amianto|sin confirmar.*amianto|posible amianto|puede.*amianto/.test(requestText);
  const selected=sanitizeSelected(ai?.selectedLines||[],allowed).filter(x=>!((noAsbestos||asbestosUncertain)&&/^DQC030/.test(x.code))&&!(/con\s+amianto|contiene\s+amianto|amianto\s+confirmado/.test(requestText)&&x.code==='DQC020'));
  const lines=enrichLines(selected,local,input),auditResult=audit({input,local,lines,ai});
  const rawQ=[...(ai?.missingQuestions||[]),...local.questions],questions=filterAnsweredQuestions([...new Set(rawQ)],input,local.measurements).slice(0,28);
  const vat=Number(input.vat)||INTERNAL_PRICING.defaultVat,totals=summarize(lines,vat);const level=estimateLevel(local,ai,lines,auditResult);
  const warnings=[...(ai?.warnings||[]),...auditResult.warnings];if(aiError)warnings.push(`La IA avanzada no respondió; se usó el motor local: ${aiError}`);if(!process.env.OPENAI_API_KEY)warnings.push('IA avanzada no configurada: el motor local funciona de forma conservadora y no analiza fotos.');
  return json({ok:true,version:'3.0.0',engine:ai?'openai':'local',pricebook:pricebookMeta,
   project:{mode:local.scope.mode,integral:local.scope.integral,type:ai?.projectType||local.scope.mode,estimateLevel:level,summary:ai?.summary||String(input.description).trim(),technicalWorks:ai?.technicalWorks?.length?ai.technicalWorks:local.technicalWorks,assumptions:ai?.assumptions||[]},
   measurements:local.measurements,
   phases:local.scope.phases.map(p=>({id:p.id,order:p.order,title:p.title,status:p.status,required:!!p.required,explicit:!!p.explicit,dependencies:p.dependencies||[],risks:p.risks||[],regulatory:p.regulatory||[]})),
   phaseReview:ai?.phaseReview||[],requiredInputs:local.scope.requiredInputs||[],
   rules:local.rules.map(r=>({id:r.id,severity:r.severity,title:r.title,checks:r.checks||[]})),regulatoryGates:local.gates,
   questions,warnings:[...new Set(warnings)].slice(0,30),blockers:auditResult.blockers.slice(0,20),audit:{status:auditResult.status,score:auditResult.score,checks:auditResult.checks},
   lines:lines.map(publicLine),totals,
   pricingPolicy:{source:INTERNAL_PRICING.source,customerComponentsHidden:true,marketUpdateIncluded:true,baseYear:2026},
   disclaimer:level==='ready_for_review'?'Borrador técnico con mediciones suficientes para revisión profesional. Debe revisarse antes de emitir la oferta contractual.':'Estimación/borrador técnico: no emitir como oferta cerrada hasta resolver datos pendientes, partidas condicionadas y mediciones.'
  });
 }catch(e){console.error('Optimus V3 error:',e);return json({error:e?.message||'Error procesando el presupuesto'},500);}
};
export const config={path:'/api/quote-agent',method:'POST'};

